DESC = "ElevenLabs Bella take (external)"
PARAS = [
    ("Toblerone fixed rising costs by making the gaps bigger. In twenty sixteen, in the UK, the four hundred gram bar became three sixty, and the one seventy gram bar became one fifty. Same length. Same box. Same price. Just wider gaps between the peaks. Mondelez blamed higher ingredient costs. That's shrinkflation. The price stays put, so you don't notice. The product shrinks instead. So check the weight, not the price. Send this to the friend who always buys the big bar.", 0.0, 1),
]
